SELECT client_ip AS "clientIp", SUM(request_count) AS "requestCount", SUM(status_4xx) AS "status4xx", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{keyword} || '%'
GROUP BY client_ip
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT client_ip
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND client_ip LIKE '%' || #{keyword} || '%'


    GROUP BY client_ip
) t

SELECT uri AS "uri", SUM(request_count) AS "requestCount", SUM(status_4xx) AS "status4xx", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND uri LIKE '%' || #{keyword} || '%'
GROUP BY uri
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT uri
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND uri LIKE '%' || #{keyword} || '%'


    GROUP BY uri
) t

SELECT client_ip AS "clientIp", uri AS "uri", method AS "method", SUM(request_count) AS "requestCount", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{clientIp} || '%'
AND uri LIKE '%' || #{uri} || '%'
GROUP BY client_ip, uri, method
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT client_ip, uri, method
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND client_ip LIKE '%' || #{clientIp} || '%'


          AND uri LIKE '%' || #{uri} || '%'


    GROUP BY client_ip, uri, method
) t

SELECT COUNT(*) FROM (
    SELECT uri
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}
      AND slow_count > 0

    GROUP BY uri
) t

SELECT method AS "method", SUM(request_count) AS "requestCount", SUM(status_4xx) AS "status4xx", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount", MAX(max_request_time_ms) AS "maxRequestTimeMs", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
GROUP BY method
ORDER BY ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) DESC ORDER BY MAX(max_request_time_ms) DESC ORDER BY SUM(request_count) DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT method
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

    GROUP BY method
) t

SELECT client_ip AS "clientIp", SUM(request_count) AS "requestCount"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}

GROUP BY client_ip
HAVING SUM(request_count) >= #{threshold}
ORDER BY SUM(request_count) DESC
LIMIT #{limit}

SELECT uri AS "uri", SUM(request_count) AS "requestCount"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}

GROUP BY uri
HAVING SUM(request_count) >= #{threshold}
ORDER BY SUM(request_count) DESC
LIMIT #{limit}

SELECT COALESCE(SUM(status_4xx), 0) AS "status4xx",
       COALESCE(SUM(status_5xx), 0) AS "status5xx",
       COALESCE(SUM(slow_count), 0) AS "slowCount",
       COALESCE(SUM(request_count), 0) AS "totalRequests"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}
